<?php foreach($rows as $r):?><tr><td><strong><?=e((string)($r['claim_number']?:'—'))?></strong><small>#<?=(int)$r['id']?></small></td><td><strong><?=e((string)$r['legal_name'])?></strong><small>DOT <?=e((string)$r['dot_number'])?></small></td><td><?=$fmtDate($r['incident_date'])?><small>Reported: <?=$fmtDate($r['claim_date'])?></small></td><td><?=e((string)($r['coverage']?:$r['claim_type']?:'—'))?><small><?=e((string)($r['claim_side']?:'—'))?></small></td><td><?=e((string)($r['insurance_carrier']?:'—'))?><small><?php $rowAdjusters=json_decode((string)($r['adjusters']??''),true);if(!is_array($rowAdjusters)||!count($rowAdjusters))$rowAdjusters=(trim((string)($r['adjuster_name']??''))!==''||trim((string)($r['adjuster_contact']??''))!=='')?[['name'=>$r['adjuster_name']??'','contact'=>$r['adjuster_contact']??'']]:[];if($rowAdjusters):foreach($rowAdjusters as $rowAdjuster):?><span class="claim-list-adjuster-name"><?=e((string)(($rowAdjuster['name']??'')?:'Unnamed adjuster'))?><?=trim((string)($rowAdjuster['contact']??''))!==''?' · '.e((string)$rowAdjuster['contact']):''?></span><?php endforeach;else:?>No adjuster<?php endif;?></small></td><td><span class="claim-status status-<?=e(strtolower(str_replace([' ','/'],'-',(string)$r['status'])))?>"><?=e((string)$r['status'])?></span></td><td class="claim-summary"><?=e((string)($r['latest_update_brief']?:'—'))?><small><?=e((string)($r['next_action']?:'No next action'))?></small></td><td><?=$fmtDate($r['follow_up_date'])?></td><td><?=e((string)($r['assigned_member_name']?:'Unassigned'))?></td><td><div class="claim-row-actions"><a class="btn light small-btn" href="<?=e(appUrl($base.'?action=edit&id='.(int)$r['id']))?>">Edit</a><button class="btn light small-btn claim-open-log" type="button" data-claim-id="<?=(int)$r['id']?>" data-claim-number="<?=e((string)$r['claim_number'])?>">Log</button><form method="post" action="<?=e(appUrl($base))?>" onsubmit="return confirm('Delete this claim record?')"><input type="hidden" name="_csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn light small-btn claim-delete" type="submit">Delete</button></form></div></td></tr><?php endforeach;?>
