</tbody></table></div><div class="claims-list-footer"><span class="muted small">Showing <?=count($rows)?> claims (maximum 500 per view).</span><span class="muted small">One row per claim number; keep follow-up fields current.</span></div></section>
<div class="claim-log-modal" id="claim-log-modal" hidden><div class="claim-log-backdrop" data-close-claim-log></div><section class="claim-log-dialog" role="dialog" aria-modal="true" aria-labelledby="claim-log-title"><header class="claim-log-header"><div><h2 id="claim-log-title">Claim Change History</h2><p id="claim-log-subtitle" class="muted"></p></div><button class="btn light small-btn" type="button" data-close-claim-log>Close</button></header><div class="claim-log-content" id="claim-log-content"><p class="muted">Select a claim to view its history.</p></div></section></div>
<script>(function(){const list=document.getElementById('claim-adjuster-list'),add=document.getElementById('claim-add-adjuster');if(list&&add){function sync(){const cards=Array.from(list.querySelectorAll('[data-adjuster-card]'));cards.forEach((card,index)=>{const title=card.querySelector('h3');if(title)title.textContent='Adjuster '+(index+1);card.querySelectorAll('[data-adjuster-field]').forEach(field=>{field.name='adjusters['+index+']['+field.dataset.adjusterField+']';});const remove=card.querySelector('[data-remove-adjuster]');if(remove)remove.hidden=cards.length===1;});add.disabled=cards.length>=4;add.textContent=cards.length>=4?'Maximum 4 Adjusters Added':'+ Add Adjuster';}add.addEventListener('click',()=>{const first=list.querySelector('[data-adjuster-card]');if(!first||list.querySelectorAll('[data-adjuster-card]').length>=4)return;const card=first.cloneNode(true);card.querySelectorAll('input').forEach(input=>input.value='');card.querySelectorAll('textarea').forEach(input=>input.value='');list.appendChild(card);sync();});list.addEventListener('click',event=>{const button=event.target.closest('[data-remove-adjuster]');if(button&&list.querySelectorAll('[data-adjuster-card]').length>1){button.closest('[data-adjuster-card]').remove();sync();}});sync();}
const modal=document.getElementById('claim-log-modal'),content=document.getElementById('claim-log-content'),subtitle=document.getElementById('claim-log-subtitle');if(!modal||!content)return;function node(tag,className,text){const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=text;return el;}function close(){modal.hidden=true;document.body.classList.remove('claim-log-open');}modal.querySelectorAll('[data-close-claim-log]').forEach(el=>el.addEventListener('click',close));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!modal.hidden)close();});document.addEventListener('click',async event=>{const button=event.target.closest('.claim-open-log');if(!button)return;modal.hidden=false;document.body.classList.add('claim-log-open');subtitle.textContent='Claim #'+button.dataset.claimNumber;content.replaceChildren(node('p','muted','Loading claim history…'));try{const response=await fetch('<?=e(appUrl('/agency/claim-logs.php'))?>?claim_id='+encodeURIComponent(button.dataset.claimId),{headers:{Accept:'application/json'},credentials:'same-origin'});const payload=await response.json();if(!response.ok||!payload.success)throw new Error(payload.message||'Could not load this claim history.');content.replaceChildren();if(!payload.logs.length){content.appendChild(node('p','muted','No change history is available for this claim yet.'));return;}payload.logs.forEach(log=>{const item=node('article','claim-log-entry');const head=node('div','claim-log-entry-heading');head.append(node('strong','',log.event_type==='created'?'Claim Created':log.event_type==='deleted'?'Claim Deleted':'Claim Updated'),node('span','',log.created_at+' UTC'));item.append(head,node('p','claim-log-actor',(log.actor_name||'Unknown user')+' · '+(log.actor_role||'Unknown role')));if(Array.isArray(log.changes)&&log.changes.length){const table=node('div','claim-log-changes');log.changes.forEach(change=>{const row=node('div','claim-log-change');row.appendChild(node('strong','',change.field||'Updated field'));const values=node('div','claim-log-values');values.append(node('p','claim-log-old','Previous: '+(change.old||'—')),node('p','claim-log-new','New: '+(change.new||'—')));row.appendChild(values);table.appendChild(row);});item.appendChild(table);}else item.appendChild(node('p','muted claim-log-no-changes','Claim saved. No field values changed.'));content.appendChild(item);});}catch(error){content.replaceChildren(node('p','claim-log-error',error.message||'Could not load claim history.'));}});})();</script>
<?php endif;?>
